//! Platform-agnostic error type and user-facing rendering.
//! (Generated by v0.6.0 Step 3 Phase 1)

use thiserror::Error;

use crate::github::GithubError;

/// Errors produced by platform clients.
///
/// Network/HTTP failures are normalized into the [`Http`], [`Network`], and
/// [`Other`] variants so the UI can render a stable message through
/// [`render_platform_error`] regardless of the underlying adapter (octocrab,
/// reqwest, …).
#[derive(Debug, Error, PartialEq, Eq)]
pub enum PlatformError {
    /// No usable token could be resolved for the platform.
    #[error("{0}")]
    Token(String),

    /// The repository's remote URL does not point at a supported platform.
    #[error("{0}")]
    NotPlatform(String),

    /// The platform API answered with an HTTP error status.
    #[error("{message}")]
    Http {
        /// HTTP status code (e.g. 401, 403, 404, 429).
        status: u16,
        /// Message reported by the API, when available.
        message: String,
        /// Whether the API signalled rate limiting.
        rate_limited: bool,
        /// Platform label ("GitHub", "GitLab", "Gitea", …).
        platform: &'static str,
    },

    /// The request failed before the API responded (DNS, TLS, connect, …).
    #[error("{0}")]
    Network(String),

    /// Any other platform error.
    #[error("{message}")]
    Other {
        platform: &'static str,
        message: String,
    },
}

/// Map [`GithubError`] → [`PlatformError`] (platform label = "GitHub").
impl From<GithubError> for PlatformError {
    fn from(e: GithubError) -> Self {
        match e {
            GithubError::Token(m) => PlatformError::Token(m),
            GithubError::NotGitHub(m) => PlatformError::NotPlatform(m),
            GithubError::Http {
                status,
                message,
                rate_limited,
            } => PlatformError::Http {
                status,
                message,
                rate_limited,
                platform: "GitHub",
            },
            GithubError::Network(m) => PlatformError::Network(m),
            GithubError::Other(m) => PlatformError::Other {
                platform: "GitHub",
                message: m,
            },
        }
    }
}

/// Map `octocrab::Error` → [`PlatformError`] (platform label = "GitHub").
///
/// Reuses the same normalization as `crate::github::error::GithubError`
/// (`From<octocrab::Error>`): GitHub errors → `Http`, Hyper errors →
/// `Network`, everything else → `Other`.
impl From<octocrab::Error> for PlatformError {
    fn from(e: octocrab::Error) -> Self {
        match e {
            octocrab::Error::GitHub { source, .. } => PlatformError::Http {
                status: source.status_code.as_u16(),
                message: source.message.clone(),
                rate_limited: source.status_code.as_u16() == 429,
                platform: "GitHub",
            },
            octocrab::Error::Hyper { .. } => PlatformError::Network(e.to_string()),
            other => PlatformError::Other {
                platform: "GitHub",
                message: other.to_string(),
            },
        }
    }
}

/// Render a platform error as a short, user-facing line.
///
/// Mirrors [`crate::github::render_error`] but routes the status-aware mapping
/// through the stored platform label so GitLab/Gitea messages stay consistent.
pub fn render_platform_error(e: &PlatformError) -> String {
    match e {
        PlatformError::Token(m) | PlatformError::NotPlatform(m) => m.clone(),
        PlatformError::Network(_) => "网络错误，请检查网络连接".to_string(),
        PlatformError::Http {
            status,
            message,
            rate_limited,
            platform,
        } => {
            if *rate_limited || *status == 429 {
                return format!("{platform} 速率限制，请稍后重试");
            }
            match *status {
                401 => format!("{platform} 认证失败，请检查令牌"),
                403 => "无权限访问该资源".to_string(),
                404 => format!("{platform} 仓库/资源不存在或无权限"),
                500..=599 => format!("{platform} 服务端错误，请稍后重试"),
                _ => {
                    if message.is_empty() {
                        format!("{platform} HTTP {status}")
                    } else {
                        message.clone()
                    }
                }
            }
        }
        PlatformError::Other { platform, message } => {
            format!("{platform} 错误: {message}")
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn from_github_error_maps_https_with_platform_label() {
        let e: PlatformError = GithubError::Http {
            status: 404,
            message: "nope".into(),
            rate_limited: false,
        }
        .into();
        assert!(matches!(
            e,
            PlatformError::Http {
                status: 404,
                platform: "GitHub",
                ..
            }
        ));
    }

    #[test]
    fn from_github_error_network_passthrough() {
        let e: PlatformError = GithubError::Network("dns fail".into()).into();
        assert!(matches!(e, PlatformError::Network(_)));
    }

    #[test]
    fn render_http_routes_by_status() {
        let e: PlatformError = GithubError::Http {
            status: 401,
            message: String::new(),
            rate_limited: false,
        }
        .into();
        assert_eq!(render_platform_error(&e), "GitHub 认证失败，请检查令牌");
    }

    #[test]
    fn render_rate_limited() {
        let e: PlatformError = GithubError::Http {
            status: 429,
            message: String::new(),
            rate_limited: false,
        }
        .into();
        assert_eq!(render_platform_error(&e), "GitHub 速率限制，请稍后重试");
    }
}
